    if current_reputation > 0.5:
        # High reputation -> lenient: boost reward for donors, extra penalty for non-donors
        if observation["action"] == "donate":
            delta = base_delta + 0.1
        else:
            delta = base_delta - 0.2
    elif current_reputation < -0.5:
