def decide(recipient_reputation, round_num, my_history):
    # Base threshold gradually increases from -0.3 to 0.5 over 15 rounds
    base_threshold = -0.3 + (round_num / 15.0) * 0.8

    # Adjust based on my own recent donating behaviour (last 3 rounds)
    recent = my_history[-3:] if len(my_history) >= 3 else my_history
    if recent:
        donation_count = sum(1 for a in recent if a == "donate")
        donation_rate = donation_count / len(recent)
        # If I donated a lot recently, I become more generous (lower threshold)
        adjustment = -0.15 * donation_rate  # range 0 to -0.15
    else:
        adjustment = 0.0

    threshold = base_threshold + adjustment

    # Hard boundaries: always donate to very high reputation, never to very low
    if recipient_reputation > 0.8:
        return True
    if recipient_reputation < -0.8:
        return False

    return recipient_reputation > threshold

