def evaluate(current_reputation, observation, my_history, round_num):
    # More aggressive reputation update: dynamics change with observer's own reputation
    # and round number (memory decay)

    # Base change for donation/non-donation
    if observation["action"] == "donate":
        base_delta = 0.5
    else:
        base_delta = -0.2

    # Reputation-dependent modulation: low reputation observers are more sensitive to donations
    # high reputation observers are more punitive for non-donations
    if current_reputation > 0.6:
        # High reputation: lenient towards donors, strict towards non-donors
        if observation["action"] == "donate":
            delta = base_delta + 0.05   # small extra reward
        else:
            delta = base_delta - 0.3    # stronger penalty
    elif current_reputation < -0.4:
        # Low reputation: eager to improve, so reward donations heavily, but also forgive non-donations a bit
        if observation["action"] == "donate":
            delta = base_delta + 0.2    # extra boost for donor
        else:
            delta = base_delta + 0.1    # penalty reduced (less harsh)
    else:
        # Neutral: use base deltas without extra modulation
        delta = base_delta

    # Apply a mild decay towards zero to prevent saturation and give recent actions more weight
    decay = 0.02 * current_reputation
    delta -= decay

    # Scale down impact in early rounds (less confident reputation)
    early_factor = min(1.0, round_num / 4.0)
    delta *= early_factor

    new_rep = current_reputation + delta
    return max(-1.0, min(1.0, new_rep))


