        donation_rate = donation_count / len(recent)
        # If I have been donating a lot, I become more generous (lower threshold)
        # If I have been stingy, I become stricter (higher threshold)
        if donation_rate > 0.5:
            adjustment = -0.2   # more generous
        else:
            adjustment = 0.1    # less generous
    else:
        adjustment = 0.0

    threshold = base_threshold + adjustment

    # Hard boundaries: always donate to very high reputation, never to very low
    if recipient_reputation > 0.9:
        return True
    if recipient_reputation < -0.9:
        return False

    return recipient_reputation > threshold
